const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];
const BIRTH_NEIGHBOR_COUNT = 3;

const keyOf = ([x, y]: Cell): string => `${x},${y}`;

const neighborsOf = ([x, y]: Cell): Cell[] =>
  [-1, 0, 1].flatMap((dx) =>
    [-1, 0, 1]
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );

const countNeighborsPerCell = (liveCells: Cell[]): Map<string, number> =>
  liveCells.flatMap(neighborsOf).reduce((counts, neighbor) => {
    const key = keyOf(neighbor);
    return counts.set(key, (counts.get(key) ?? 0) + 1);
  }, new Map<string, number>());

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const neighborCounts = countNeighborsPerCell(liveCells);
  const liveKeys = new Set(liveCells.map(keyOf));
  const neighborCountOf = (cell: Cell): number =>
    neighborCounts.get(keyOf(cell)) ?? 0;

  const survivors = liveCells.filter((cell) =>
    SURVIVAL_NEIGHBOR_COUNTS.includes(neighborCountOf(cell)),
  );

  const births = liveCells
    .flatMap(neighborsOf)
    .filter((cell) => !liveKeys.has(keyOf(cell)))
    .filter((cell) => neighborCountOf(cell) === BIRTH_NEIGHBOR_COUNT)
    .filter(dedupedByKey());

  return [...survivors, ...births];
}

const dedupedByKey = (): ((cell: Cell) => boolean) => {
  const seen = new Set<string>();
  return (cell: Cell) => {
    const key = keyOf(cell);
    return seen.has(key) ? false : Boolean(seen.add(key));
  };
};

